CREATE TABLE "public"."Mixed Case" (
    "Id" integer NOT NULL,
    "a""b" text,
    CONSTRAINT "Mixed Case_pkey" PRIMARY KEY ("Id")
);

CREATE TABLE "shop"."events" (
    "id" integer,
    "at" date NOT NULL
) PARTITION BY RANGE (at);

CREATE TABLE "shop"."orders" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "customer_id" integer NOT NULL,
    "total" numeric(10,2) DEFAULT 0 NOT NULL,
    "qty" integer DEFAULT 1 NOT NULL,
    "total_with_tax" numeric GENERATED ALWAYS AS ((total * 1.1)) STORED,
    "status" text DEFAULT 'new'::text NOT NULL,
    "during" tsrange,
    CONSTRAINT "orders_pk" PRIMARY KEY (id),
    CONSTRAINT "orders_customer_id_fkey" FOREIGN KEY (customer_id) REFERENCES shop.customers(id) ON UPDATE SET NULL ON DELETE CASCADE,
    CONSTRAINT "positive_total" CHECK (total >= 0::numeric),
    CONSTRAINT "no_overlap" EXCLUDE USING gist (customer_id WITH =, during WITH &&)
);

CREATE INDEX orders_lower ON shop.orders USING btree (lower(status));

CREATE INDEX orders_status ON shop.orders USING btree (status) WHERE (status <> 'done'::text);

CREATE TRIGGER orders_audit AFTER DELETE ON shop.orders FOR EACH STATEMENT EXECUTE FUNCTION shop.touch();

CREATE TRIGGER orders_touch BEFORE INSERT OR UPDATE ON shop.orders FOR EACH ROW EXECUTE FUNCTION shop.touch();

ALTER TABLE "shop"."orders" DISABLE TRIGGER "orders_audit";

COMMENT ON TABLE "shop"."orders" IS 'Customer''s orders';

COMMENT ON COLUMN "shop"."orders"."total" IS 'Gross total';
